cd /tmp && cat > q9.v <<'EOF'
Require Import Syntax Notations Helpers Typing Subtyping Bigstep ViewpointAdaptation.
From Stdlib Require Import List Lia Arith.
Import ListNotations.
Ltac qsolve :=
  intros;
  repeat match goal with
    | p : qualified_type |- _ => destruct p
    | q : q |- _ => destruct q
    | r : q_r |- _ => destruct r
    | c : q_c |- _ => destruct c
    | f : q_f |- _ => destruct f
    | aa : a |- _ => destruct aa
    | H : _ \/ _ |- _ => destruct H
  end;
  cbn in *;
  repeat match goal with
    | H : q_subtype _ _ |- _ => inversion H; subst; clear H
  end;
  cbn in *;
  try discriminate;
  try congruence;
  try tauto;
  try (apply q_bot);
  try (apply q_rd);
  try (apply q_refl; discriminate);
  try assumption.

Lemma param_override_transfer : forall (qArg qTy qc sqOld sqNew : q),
  q_subtype qArg (vpa_mutability_qq_abstract_state qTy sqOld) ->
  q_subtype (vpa_mutability_qq_abstract_state qc sqOld) sqNew ->
  q_subtype qArg (vpa_mutability_qq_abstract_state qTy sqNew).
Proof. qsolve. Show. Abort.
EOF
